"use client";

import { useState, useMemo } from "react";
import type { RecipeAEOBlock } from "./page";

type Props = {
  recipes: RecipeAEOBlock[];
};

const PAGE_SIZE = 24;

const COOKING_LABELS: Record<string, string> = {
  baked: "Stekeovn",
  fried: "Pannesteking",
  boiled: "Koking",
  raw: "Rå",
  mixed: "Blandet",
  unknown: "Ukjent",
};

function Badge({ label, muted }: { label: string; muted?: boolean }) {
  return (
    <span
      className={`inline-block rounded px-2 py-0.5 text-xs ${
        muted
          ? "bg-[#EAEAEA]/5 text-[#EAEAEA]/40"
          : "bg-[#EAEAEA]/10 text-[#EAEAEA]/70"
      }`}
    >
      {label}
    </span>
  );
}

function RecipeCard({ block }: { block: RecipeAEOBlock }) {
  const [open, setOpen] = useState(false);
  const { recipe, primary_answer, faqs, micro_answers, metadata } = block;

  const topFaqs = faqs.slice(0, 3);
  const hasMoreFaqs = faqs.length > 3;

  return (
    <article className="border border-[#EAEAEA]/10 rounded-lg transition-colors hover:border-[#EAEAEA]/20">
      {/* Card header — always visible */}
      <button
        onClick={() => setOpen((v) => !v)}
        className="w-full text-left px-6 py-5 flex items-start justify-between gap-4"
        aria-expanded={open}
      >
        <div className="flex-1 min-w-0">
          <h3 className="text-base font-medium text-[#EAEAEA] leading-snug truncate">
            {recipe}
          </h3>
          <div className="mt-2 flex flex-wrap gap-1.5">
            {metadata.category && (
              <Badge label={metadata.category} />
            )}
            {metadata.cooking_method && metadata.cooking_method !== "unknown" && (
              <Badge
                label={COOKING_LABELS[metadata.cooking_method] ?? metadata.cooking_method}
                muted
              />
            )}
            {metadata.allergens.map((a) => (
              <Badge key={a} label={a} muted />
            ))}
          </div>
        </div>
        <span
          className={`mt-0.5 flex-shrink-0 text-[#EAEAEA]/40 transition-transform ${
            open ? "rotate-180" : ""
          }`}
          aria-hidden
        >
          ▾
        </span>
      </button>

      {/* Expanded content */}
      {open && (
        <div className="px-6 pb-7 pt-1 border-t border-[#EAEAEA]/10 space-y-6">
          {/* Primary answer */}
          <div>
            <p className="text-xs uppercase tracking-[0.18em] text-[#EAEAEA]/40 mb-2">
              Primærsvar
            </p>
            <p className="text-base leading-relaxed text-[#EAEAEA]">
              {primary_answer}
            </p>
          </div>

          {/* FAQs */}
          {topFaqs.length > 0 && (
            <div>
              <p className="text-xs uppercase tracking-[0.18em] text-[#EAEAEA]/40 mb-3">
                FAQ ({faqs.length} spørsmål)
              </p>
              <div className="divide-y divide-[#EAEAEA]/10 border-t border-[#EAEAEA]/10">
                {faqs.map((faq) => (
                  <details key={faq.question} className="py-3.5 group">
                    <summary className="cursor-pointer list-none text-sm leading-snug text-[#EAEAEA]/80 hover:text-[#EAEAEA] flex justify-between gap-3">
                      <span>{faq.question}</span>
                      <span className="flex-shrink-0 text-[#EAEAEA]/30 group-open:rotate-180 transition-transform">
                        ▾
                      </span>
                    </summary>
                    <p className="mt-2.5 text-sm leading-relaxed text-[#B0B0B0]">
                      {faq.answer}
                    </p>
                    <div className="mt-2 flex gap-2">
                      <Badge label={faq.type} muted />
                      <Badge label={`score ${faq.score}`} muted />
                    </div>
                  </details>
                ))}
              </div>
              {hasMoreFaqs && (
                <p className="mt-2 text-xs text-[#EAEAEA]/30">
                  + {faqs.length - 3} skjulte spørsmål (se JSON-eksport for alle)
                </p>
              )}
            </div>
          )}

          {/* Micro answers */}
          {micro_answers.length > 0 && (
            <div>
              <p className="text-xs uppercase tracking-[0.18em] text-[#EAEAEA]/40 mb-2">
                Mikrosvar
              </p>
              <ul className="space-y-1.5">
                {micro_answers.map((m, i) => (
                  <li key={i} className="text-sm leading-relaxed text-[#B0B0B0]">
                    — {m}
                  </li>
                ))}
              </ul>
            </div>
          )}

          {/* Ingredients preview */}
          {metadata.ingredients.length > 0 && (
            <div>
              <p className="text-xs uppercase tracking-[0.18em] text-[#EAEAEA]/40 mb-2">
                Ingredienser ({metadata.ingredients.length})
              </p>
              <p className="text-sm text-[#EAEAEA]/40 leading-relaxed">
                {metadata.ingredients.slice(0, 8).join(", ")}
                {metadata.ingredients.length > 8 && " …"}
              </p>
            </div>
          )}
        </div>
      )}
    </article>
  );
}

export function RecipeList({ recipes }: Props) {
  const [query, setQuery] = useState("");
  const [shown, setShown] = useState(PAGE_SIZE);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return recipes;
    return recipes.filter(
      (r) =>
        r.recipe.toLowerCase().includes(q) ||
        (r.metadata.category ?? "").toLowerCase().includes(q) ||
        r.metadata.allergens.some((a) => a.toLowerCase().includes(q))
    );
  }, [recipes, query]);

  // Reset pagination when search changes
  const handleSearch = (e: React.ChangeEvent<HTMLInputElement>) => {
    setQuery(e.target.value);
    setShown(PAGE_SIZE);
  };

  const visible = filtered.slice(0, shown);
  const hasMore = shown < filtered.length;

  return (
    <div className="mt-10">
      {/* Search */}
      <div className="mb-8">
        <input
          type="search"
          value={query}
          onChange={handleSearch}
          placeholder="Søk etter oppskrift, kategori eller allergen…"
          className="w-full max-w-xl rounded-md border border-[#EAEAEA]/20 bg-[#EAEAEA]/5 px-4 py-3 text-sm text-[#EAEAEA] placeholder-[#EAEAEA]/30 outline-none transition focus:border-[#EAEAEA]/50"
        />
        <p className="mt-2 text-xs text-[#EAEAEA]/30">
          {filtered.length === recipes.length
            ? `${recipes.length} oppskrifter`
            : `${filtered.length} av ${recipes.length} oppskrifter`}
        </p>
      </div>

      {/* Grid */}
      {visible.length > 0 ? (
        <>
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
            {visible.map((block) => (
              <RecipeCard key={block.recipe} block={block} />
            ))}
          </div>

          {hasMore && (
            <div className="mt-10 text-center">
              <button
                onClick={() => setShown((n) => n + PAGE_SIZE)}
                className="rounded-md border border-[#EAEAEA]/20 px-6 py-2.5 text-sm text-[#EAEAEA]/70 transition hover:border-[#EAEAEA]/40 hover:text-[#EAEAEA]"
              >
                Last inn flere ({filtered.length - shown} gjenstår)
              </button>
            </div>
          )}
        </>
      ) : (
        <p className="mt-12 text-center text-[#EAEAEA]/40">
          Ingen oppskrifter matcher søket.
        </p>
      )}
    </div>
  );
}
